214	<script>
215	(function(){
216	  var LAYOUT_KEY = 'coach888_layout';
217	  var TITLES_KEY = 'coach888_titles';
218	  var BADGES_KEY = 'coach888_badges';
219	
220	  function renumber(grid){
221	    grid.querySelectorAll('.item .num').forEach(function(el, i){ el.textContent = i + 1; });
222	    var title = grid.previousElementSibling;
223	    if (title && title.classList.contains('section-title')) {
224	      var countEl = title.querySelector('.count');
225	      if (countEl) countEl.textContent = grid.querySelectorAll('.item').length + '項';
226	    }
227	  }
228	
229	  function saveLayout(){
230	    var layout = {};
231	    document.querySelectorAll('.grid').forEach(function(grid){
232	      layout[grid.dataset.section] = Array.prototype.map.call(grid.querySelectorAll('.item'), function(it){ return it.dataset.url; });
233	    });
234	    localStorage.setItem(LAYOUT_KEY, JSON.stringify(layout));
235	    // 清掉2026-07-20版之前的舊格式（每組各自存一個key），避免新舊格式打架
236	    document.querySelectorAll('.grid').forEach(function(grid){
237	      localStorage.removeItem('coach888_order_' + grid.dataset.section);
238	    });
239	  }
240	
241	  function loadLayout(){
242	    var raw = localStorage.getItem(LAYOUT_KEY);
243	    if (raw) {
244	      try { return JSON.parse(raw); } catch(e){}
245	    }
246	    // 相容舊版：只支援組內排序、每組各自一個key，讀出來當初始佈局
247	    var legacy = {}, found = false;
248	    document.querySelectorAll('.grid').forEach(function(grid){
249	      var old = localStorage.getItem('coach888_order_' + grid.dataset.section);
250	      if (old) {
251	        try { legacy[grid.dataset.section] = JSON.parse(old); found = true; } catch(e){}
252	      }
253	    });
254	    return found ? legacy : null;
255	  }
256	
257	  function saveTitles(){
258	    var titles = {};
259	    document.querySelectorAll('.section-title').forEach(function(t){
260	      var span = t.querySelector('.title-text');
261	      if (span) titles[t.dataset.section] = span.textContent.trim();
262	    });
263	    localStorage.setItem(TITLES_KEY, JSON.stringify(titles));
264	  }
265	
266	  function applyTitles(){
267	    var raw = localStorage.getItem(TITLES_KEY);
268	    if (!raw) return;
269	    try {
270	      var titles = JSON.parse(raw);
271	      document.querySelectorAll('.section-title').forEach(function(t){
272	        var span = t.querySelector('.title-text');
273	        if (span && titles[t.dataset.section] != null) span.textContent = titles[t.dataset.section];
274	      });
275	    } catch(e){}
276	  }
277	
278	  function saveBadges(){
279	    var badges = {};
280	    document.querySelectorAll('.item').forEach(function(it){
281	      var b = it.querySelector('.badge');
282	      if (b) badges[it.dataset.url] = b.textContent.trim();
283	    });
284	    localStorage.setItem(BADGES_KEY, JSON.stringify(badges));
285	  }
286	
287	  function applyBadges(){
288	    var raw = localStorage.getItem(BADGES_KEY);
289	    if (!raw) return;
290	    try {
291	      var badges = JSON.parse(raw);
292	      document.querySelectorAll('.item').forEach(function(it){
293	        var b = it.querySelector('.badge');
294	        if (b && badges[it.dataset.url] != null) b.textContent = badges[it.dataset.url];
295	      });
296	    } catch(e){}
297	  }
298	
299	  function bindEditable(el, onSave){
300	    el.addEventListener('keydown', function(e){
301	      if (e.key === 'Enter') { e.preventDefault(); el.blur(); }
302	    });
303	    el.addEventListener('blur', onSave);
304	  }
305	
306	  function applyLayout(){
307	    var layout = loadLayout();
308	    if (!layout) return;
309	    var allItems = {};
310	    document.querySelectorAll('.item').forEach(function(it){ allItems[it.dataset.url] = it; });
311	    document.querySelectorAll('.grid').forEach(function(grid){
312	      var ids = layout[grid.dataset.section];
313	      if (!ids) return;
314	      ids.forEach(function(id){
315	        if (allItems[id]) grid.appendChild(allItems[id]);
316	      });
317	    });
318	  }
319	
320	  function getDragAfterElement(grid, y){
321	    var els = Array.prototype.slice.call(grid.querySelectorAll('.item:not(.dragging)'));
322	    return els.reduce(function(closest, child){
323	      var box = child.getBoundingClientRect();
324	      var offset = y - box.top - box.height / 2;
325	      if (offset < 0 && offset > closest.offset) {
326	        return { offset: offset, element: child };
327	      }
328	      return closest;
329	    }, { offset: -Infinity, element: null }).element;
330	  }
331	
332	  // 2026-07-20 改用滑鼠事件手刻拖曳（不用 HTML5 原生 draggable API）：
333	  // .item 內部有 <a class="name" href="..."> 連結，瀏覽器對連結元素有自己的
334	  // 原生拖曳行為，跟外層 draggable="true" 互相打架，導致放開時被瀏覽器判定
335	  // 為無效拖放而彈回原位（教練實測回報「都會被打回原來的位置」）。改成監聽
336	  // drag-handle 的 mousedown/mousemove/mouseup 手動搬移 DOM，完全不觸發原生
337	  // 拖放機制，也就不會有這個衝突。
338	  var dragEl = null;
339	  var sourceGrid = null;
340	
341	  function onMouseMove(e){
342	    if (!dragEl) return;
343	    var el = document.elementFromPoint(e.clientX, e.clientY);
344	    var targetGrid = el ? el.closest('.grid') : null;
345	    if (!targetGrid) return;
346	    var afterEl = getDragAfterElement(targetGrid, e.clientY);
347	    if (afterEl == null) {
348	      targetGrid.appendChild(dragEl);
349	    } else if (afterEl !== dragEl) {
350	      targetGrid.insertBefore(dragEl, afterEl);
351	    }
352	  }
353	
354	  function onMouseUp(){
355	    if (!dragEl) return;
356	    dragEl.classList.remove('dragging');
357	    var targetGrid = dragEl.closest('.grid');
358	    renumber(sourceGrid);
359	    if (targetGrid !== sourceGrid) renumber(targetGrid);
360	    saveLayout();
361	    dragEl = null;
362	    sourceGrid = null;
363	    document.removeEventListener('mousemove', onMouseMove);
364	    document.removeEventListener('mouseup', onMouseUp);
365	  }
366	
367	  applyLayout();
368	  applyTitles();
369	  applyBadges();
370	
371	  document.querySelectorAll('.item').forEach(function(item){
372	    var handle = item.querySelector('.drag-handle');
373	    handle.addEventListener('mousedown', function(e){
374	      e.preventDefault();
375	      dragEl = item;
376	      sourceGrid = item.closest('.grid');
377	      item.classList.add('dragging');
378	      document.addEventListener('mousemove', onMouseMove);
379	      document.addEventListener('mouseup', onMouseUp);
380	    });
381	  });
382	
383	  document.querySelectorAll('.title-text').forEach(function(el){ bindEditable(el, saveTitles); });
384	  document.querySelectorAll('.badge').forEach(function(el){ bindEditable(el, saveBadges); });
385	
386	  document.querySelectorAll('.grid').forEach(renumber);
387	
388	  var toastEl = document.getElementById('toast');
389	  function toast(msg){
390	    toastEl.textContent = msg;
391	    toastEl.classList.add('show');
392	    setTimeout(function(){ toastEl.classList.remove('show'); }, 2200);
393	  }
394	
395	  document.getElementById('btnCopy').addEventListener('click', function(){
396	    var lines = [];
397	    document.querySelectorAll('.section-title').forEach(function(title, idx){
398	      var grid = document.querySelectorAll('.grid')[idx];
399	      lines.push(title.textContent.trim());
400	      grid.querySelectorAll('.item').forEach(function(item){
401	        var num = item.querySelector('.num').textContent;
402	        var name = item.querySelector('.name').textContent;
403	        var url = item.dataset.url;
404	        var badge = item.querySelector('.badge').textContent.trim();
405	        lines.push('  ' + num + '. ' + name + '  ' + url + '  [' + badge + ']');
406	      });
407	      lines.push('');
408	    });
409	    var text = lines.join('\n');
410	    navigator.clipboard.writeText(text).then(function(){
411	      toast('已複製目前排序，貼給小龍蝦即可固化進正式檔案');
412	    }, function(){
413	      toast('複製失敗，請手動選取畫面上的文字');
414	    });
415	  });
416	})();
417	</script>
418	</body>
419	</html>
