function saveCollapse(){
  var state = {};
  document.querySelectorAll('.section-block').forEach(function(block){
    var grid = block.querySelector('.grid');
    if (grid) state[grid.dataset.section] = block.classList.contains('collapsed');
  });
  localStorage.setItem(COLLAPSE_KEY, JSON.stringify(state));
}

function applyCollapse(){
  var raw = localStorage.getItem(COLLAPSE_KEY);
  if (!raw) return;
  try {
    var state = JSON.parse(raw);
    document.querySelectorAll('.section-block').forEach(function(block){
      var grid = block.querySelector('.grid');
      if (grid && state[grid.dataset.section]) block.classList.add('collapsed');
    });
  } catch(e){}
}

function renumberSections(){
  document.querySelectorAll('.section-title').forEach(function(title, i){
    var idxEl = title.querySelector('.idx');
    if (idxEl) idxEl.textContent = (CHINESE_NUM[i] || (i + 1)) + '、';
  });
}

function wireItem(item){
  var handle = item.querySelector('.drag-handle');
  handle.addEventListener('mousedown', function(e){
    e.preventDefault();
    dragEl = item;
    sourceGrid = item.closest('.grid');
    item.classList.add('dragging');
    document.addEventListener('mousemove', onMouseMove);
    document.addEventListener('mouseup', onMouseUp);
  });
  var del = item.querySelector('.item-del');
  del.addEventListener('click', function(){
    var name = item.querySelector('.name').textContent.trim();
    if (!confirm('確定要刪除「' + name + '」這個項目嗎？')) return;
    var grid = item.closest('.grid');
    item.remove();
    renumber(grid);
    saveLayout();
    toast('已刪除「' + name + '」');
  });
  var nameEl = item.querySelector('.name');
  var urlEl = item.querySelector('.url');
  var badgeEl = item.querySelector('.badge');
  bindEditable(nameEl, function(){ nameEl.textContent = nameEl.textContent.trim(); saveLayout(); });
  bindEditable(urlEl, function(){ urlEl.textContent = urlEl.textContent.trim(); saveLayout(); });
  bindEditable(badgeEl, saveBadges);
}

function addItem(grid){
  var name = prompt('項目名稱？');
  if (name === null || name.trim() === '') return;
  var url = prompt('網址？（例如 https://xxx.bymyway.com/）');
  if (url === null || url.trim() === '') return;
  var badge = prompt('標籤文字？（例如：常用／私藏·BNI／後臺／待退場）', '常用');
  if (badge === null) badge = '';
  name = name.trim(); url = url.trim(); badge = badge.trim();

  var item = document.createElement('div');
  item.className = 'item';
  item.dataset.url = url;
  item.innerHTML = '<span class="drag-handle">⠿</span>' +
    '<div class="num">0</div>' +
    '<a class="name" href="' + url.replace(/"/g, '&quot;') + '" target="_blank" contenteditable="true" spellcheck="false">' + name.replace(/</g, '&lt;') + '</a>' +
    '<div class="url" contenteditable="true" spellcheck="false">' + url.replace(/</g, '&lt;') + '</div>' +
    '<div class="badge star" contenteditable="true" spellcheck="false">' + badge.replace(/</g, '&lt;') + '</div>' +
    '<span class="item-del" title="刪除這個項目">✕</span>';
  grid.appendChild(item);
  wireItem(item);
  renumber(grid);
  saveLayout();
  saveBadges();
  toast('已新增「' + name + '」，記得按上方複製排序貼給AI固化');
}

function wireSectionBlock(block){
  var title = block.querySelector('.section-title');
  var grid = block.querySelector('.grid');
  var arrow = title.querySelector('.toggle-arrow');
  arrow.addEventListener('click', function(){
    block.classList.toggle('collapsed');
    saveCollapse();
  });
  var delBtn = title.querySelector('.section-del');
  delBtn.addEventListener('click', function(){
    var name = title.querySelector('.title-text').textContent.trim();
    if (!confirm('確定要刪除整個「' + name + '」分類嗎？裡面所有項目都會一起消失。')) return;
    block.remove();
    renumberSections();
    saveLayout();
    saveTitles();
    toast('已刪除「' + name + '」分類');
  });
  var titleText = title.querySelector('.title-text');
  bindEditable(titleText, saveTitles);
  var addBtn = block.querySelector('.btn-add-item');
  addBtn.addEventListener('click', function(){ addItem(grid); });
}

function addSection(){
  var name = prompt('新分類的標題？');
  if (name === null || name.trim() === '') return;
  name = name.trim();
  var key = 'custom' + Date.now();

  var block = document.createElement('div');
  block.className = 'section-block';
  block.innerHTML =
    '<div class="section-title" data-section="' + key + '">' +
      '<span class="toggle-arrow" title="收合/展開">▼</span>' +
      '<span class="idx">、</span>' +
      '<span class="title-text" contenteditable="true" spellcheck="false">' + name.replace(/</g, '&lt;') + '</span> ' +
      '<span class="count">0項</span>' +
      '<span class="section-del" title="刪除整個分類">🗑</span>' +
    '</div>' +
    '<div class="grid" data-section="' + key + '"></div>' +
    '<button class="btn-add-item" data-section="' + key + '">+ 新增項目</button>';
  document.querySelector('.wrap').appendChild(block);
  wireSectionBlock(block);
  renumberSections();
  saveTitles();
  toast('已新增「' + name + '」分類，接著可以按「+ 新增項目」加內容');
}

